import math

def sort_records(mapping, by='key', reverse=False):
    if not isinstance(mapping, dict) or by not in ('key','value') or type(reverse) is not bool:
        raise ValueError('parameters')
    for key, value in mapping.items():
        if not isinstance(key,str) or isinstance(value,bool) or not isinstance(value,(int,float)) or (isinstance(value,float) and not math.isfinite(value)):
            raise ValueError('key/value types')
    result=sorted(mapping.items(),key=lambda pair:pair[0])
    if by=='key':
        return list(reversed(result)) if reverse else result
    return sorted(result,key=lambda pair:pair[1],reverse=reverse)
