def timed(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        start = perf_counter()
        try:
            return fn(*args, **kwargs)
        finally:
            print(f'{fn.__name__}: {perf_counter() - start:.6f}s')
    return wrapper

@timed
def add(a, b):
    return a + b
assert add(2, 3) == 5
assert add.__name__ == 'add'
