import os
from pathlib import Path

def list_files(root):
    root=Path(root)
    files=[];errors=[]
    def error(path,exc):
        errors.append({'path':path.relative_to(root).as_posix(),'errno':exc.errno or 0})
    def visit(directory):
        try:
            with os.scandir(directory) as scan:
                entries=sorted(scan,key=lambda item:item.name)
        except OSError as exc:
            error(directory,exc);return
        for entry in entries:
            path=Path(entry.path)
            try:
                if entry.is_symlink():continue
                if entry.is_dir(follow_symlinks=False):visit(path)
                elif entry.is_file(follow_symlinks=False):files.append(path.relative_to(root).as_posix())
            except OSError as exc:error(path,exc)
    visit(root)
    return {'files':sorted(files),'errors':sorted(errors,key=lambda item:(item['path'],item['errno']))}
```

